const CONTEXT_DEPTHS: [usize; 6] = [0, 1, 2, 4, 8, 16];
const OFFSETS: [usize; 6] = [0, 1, 3, 7, 23, 279];
const LEVELS: usize = CONTEXT_DEPTHS.len();
const DEPTH: usize = LEVELS - 1;

fn context_index(history: u16, level: usize) -> Result<usize> {
    let depth = *CONTEXT_DEPTHS.get(level).ok_or("sparse CTS level outside bounds")?;
    let offset = *OFFSETS.get(level).ok_or("sparse CTS offset outside bounds")?;
    // 最新bitを元treeの最上位branchにする。同じsuffixをcompact blockへ写す。
    let key = usize::from(history.reverse_bits()) >> (16 - depth);
    let index = offset.checked_add(key).ok_or("sparse CTS context index overflow")?;
    if index >= NODES {
        return Err("sparse CTS context node outside bounds".into());
    }
    Ok(index)
}

#[cfg(khc_sparse_context_audit)]
pub(super) fn audit_context(history: u16, level: usize) -> Result<usize> {
    context_index(history, level)
}
#[cfg(khc_sparse_context_audit)]
pub(super) fn audit_sparse_layout() -> (usize, usize, usize, usize) {
    (NODES, LEVELS, std::mem::size_of::<Node>(), std::mem::size_of::<Prediction>())
}

